    /// Build a minimal `Cli` suitable for a single `complete_once` call.
    /// Defaults that affect the dispatch are explicit here; everything
    /// else is left at `clap`'s default. Quiet is on so test stdout
    /// stays clean — the dispatcher's fallback log goes through
    /// `eprintln` not stdout.
    fn dummy_cli() -> Cli {
        Cli::try_parse_from(["zoder", "exec"]).expect("clap parse")
    }

    /// Build a minimal `Cli` for a `run_loop_review_once` call. No `-m`, no
    /// allowlists: the caller passes the reviewer model as the
    /// `reviewer_override` argument, which is priority 1 in candidate
    /// ordering, and the dispatch loop walks `plan.candidates` — so the
    /// reviewer dispatch is pinned without the `--reviewer-pool-routes`
    /// machinery (whose author-chain guard would otherwise demand a
    /// resolved author route). The scenario layer sees the free corpus and
    /// produces a deterministic reviewer chain from it.
    fn review_cli() -> Cli {
        Cli::try_parse_from(["zoder", "exec"]).expect("clap parse")
    }

    /// OpenAI-shaped chat completion wrapping a structured JSON review.
    /// The review is the caller's, so mounts can vary the verdict and
    /// findings without duplicating the wire shape.
    fn openai_completion(review: serde_json::Value) -> String {
        serde_json::json!({
            "choices": [{
                "message": {"role": "assistant", "content": review.to_string()},
                "finish_reason": "stop"
            }],
            "usage": {"prompt_tokens": 5, "completion_tokens": 10, "total_tokens": 15}
        })
        .to_string()
    }

    /// Mount a reviewer reply whose single finding is a FALSE
    /// "undefined" claim: the file the finding points at DEFINES the
    /// symbol the title calls missing. The loop review must drop the
    /// finding and record the disproving evidence in
    /// `filtered_findings`. The location's line number intentionally
    /// does not match the defining line: a filter that only looks at
    /// the cited line would keep the finding, so the pass also proves
    /// the whole-file scan is what does the work.
    async fn mount_200_review_with_false_undefined_finding(server: &MockServer) {
        let review = serde_json::json!({
            "verdict": "request_changes",
            "summary": "the constant is not defined in this chunk",
            "findings": [{
                "severity": "critical",
                "title": "RETRY_LIMIT is undefined",
                "body": "the constant is not defined in this chunk",
                "location": "pkg/mod.py:4"
            }],
            "next_steps": []
        });
        let body = openai_completion(review);
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(200).set_body_string(body))
            .mount(server)
            .await;
    }

    /// Production-path proof for the loop review's false-"undefined"
    /// filter. This drives the real [`run_loop_review_once`] — the loop
    /// reviewer's one-call entry — end to end: a wiremock server stands
    /// in for the reviewer provider, its reply carries one false
    /// finding, and the review's worktree root (a real tempdir) defines
    /// the symbol the finding claims is missing. The filter call inside
    /// `run_loop_review_once` (the `filter_false_undefined_findings`
    /// over the working-tree reader) must drop the finding before it is
    /// returned; with that call removed the returned `ReviewOutput`
    /// still carries the finding and has no `filtered_findings`, so
    /// this test fails. It reaches the loop path only — it does not
    /// exercise `cmd_review`'s standalone call site.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn run_loop_review_once_drops_a_false_undefined_finding() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        mount_200_review_with_false_undefined_finding(&server).await;
        // The reviewer dispatch is pinned through the call's
        // `reviewer_override` argument (candidate priority 1); the corpus
        // marks the reviewer free so the policy gate passes.
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");

        // The review's worktree root: a real tempdir whose file defines the
        // symbol the finding claims is missing. `run_loop_review_once` reads
        // the location's path relative to this root.
        let root_dir = tempfile::tempdir().unwrap();
        let root = root_dir.path();
        std::fs::create_dir_all(root.join("pkg")).unwrap();
        std::fs::write(root.join("pkg/mod.py"), "RETRY_LIMIT = 3\n").unwrap();
        let diff = concat!(
            "diff --git a/pkg/mod.py b/pkg/mod.py\n",
            "index 1111111..2222222 100644\n",
            "--- a/pkg/mod.py\n",
            "+++ b/pkg/mod.py\n",
            "@@ -1,2 +1,3 @@\n",
            " RETRY_LIMIT = 3\n",
            "+RETRY_LIMIT_UNUSED = 4\n"
        );
        // No route flags: the `Some("working-model/reviewer")` override
        // argument below is what pins the reviewer dispatch.
        let cli = review_cli();

        let (review, _, _, chunks, _) = run_loop_review_once(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            "review the diff",
            diff,
            "working tree",
            "",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            root,
        )
        .await
        .expect("the loop review completes against the mock reviewer");
        assert_eq!(chunks, 1, "one chunk for a diff this small");
        // The false finding must be GONE from the returned review.
        assert!(
            review.findings.is_empty(),
            "the disproved finding must not survive the loop review: {review:?}"
        );
        // ...and PRESENT in `filtered_findings` with its symbol and the
        // defining line that disproves it.
        assert_eq!(
            review.filtered_findings.len(),
            1,
            "the loop must keep the disproving evidence: {review:?}"
        );
        let record = &review.filtered_findings[0];
        assert_eq!(record["symbol"], "RETRY_LIMIT");
        assert!(
            record["evidence"]
                .as_str()
                .unwrap()
                .contains("RETRY_LIMIT = 3"),
            "{record}"
        );
        // The only finding was disproved, so a blocking verdict is
        // downgraded to `comment`, never `approve`.
        assert_eq!(review.verdict, "comment", "{review:?}");
    }

    /// D10.7: one review reads a given post-image file ONCE.
    ///
    /// `context_for` (the cross-chunk header), `filter_false_undefined_findings`
    /// and the confirmation grounding each read the reviewed files, and a
    /// branch read is a `git show HEAD:<path>` subprocess. Before the fix each
    /// consumer had its own reader: the header read `pkg/mod.py` while planning
    /// and re-read it on every re-plan/fallback, and the filter read it again,
    /// so one small review forked the same file several times. All three now
    /// share one per-review `PostImages` cache.
    ///
    /// The reader is injected (the counting closure below) so the read count is
    /// observable without patching `std::fs`: `reads()` counts calls to the
    /// UNDERLYING reader, i.e. real reads, not cache hits. Asserted as an
    /// exact count of one per distinct path.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn post_image_read_once_per_file() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        mount_200_review_with_false_undefined_finding(&server).await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");

        let root_dir = tempfile::tempdir().unwrap();
        let root = root_dir.path();
        std::fs::create_dir_all(root.join("pkg")).unwrap();
        std::fs::write(root.join("pkg/mod.py"), "RETRY_LIMIT = 3\n").unwrap();
        let diff = concat!(
            "diff --git a/pkg/mod.py b/pkg/mod.py\n",
            "index 1111111..2222222 100644\n",
            "--- a/pkg/mod.py\n",
            "+++ b/pkg/mod.py\n",
            "@@ -1,2 +1,3 @@\n",
            " RETRY_LIMIT = 3\n",
            "+RETRY_LIMIT_UNUSED = 4\n"
        );
        let cli = review_cli();

        // The counting reader stands in for production's disk read: it runs
        // once per ACTUAL read, so `reads()` is a true read count, not a hit
        // count.
        let raw = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let read_counter = raw.clone();
        let post_image = crate::config_cache::PostImages::new(move |path: &str| {
            read_counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            std::fs::read_to_string(root.join(path)).ok()
        });

        let (review, _, _, chunks, _) = run_loop_review_once_with_reader(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            "review the diff",
            diff,
            "working tree",
            "",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            &post_image,
        )
        .await
        .expect("the loop review completes against the mock reviewer");
        assert_eq!(chunks, 1, "one chunk for a diff this small");
        // Sanity: the filter really did run and read the file, so the count
        // below is evidence that the read happened, not that nothing read.
        assert_eq!(review.filtered_findings.len(), 1, "{review:?}");
        assert_eq!(
            raw.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "pkg/mod.py must be read exactly once per review, shared by the \
             context header and the false-\"undefined\" filter"
        );
    }

    /// D5.2: one review loads the engine ONCE.
    ///
    /// Before the fix, a review re-read the config, the engine TOML and the
    /// multi-megabyte model corpus on every reviewer dispatch, on every
    /// invalid-verdict repair, and once more on each recorded fallback
    /// failure — and the loop did it three times per iteration just to build
    /// the chain, the author families and the review itself. The engine is
    /// now loaded once and borrowed (`&Engine`) by `build_reviewer_plan`,
    /// `dispatch_reviewer_for_model` and the repair/failure paths.
    ///
    /// The counter is keyed by `Config::home()` ([`crate::engine_load_count_for`]),
    /// so this test reads the count for ITS fixture home (which `HomeGuard` makes the current one) and
    /// asserts on the DELTA it caused, never an absolute count. A global
    /// counter would be blind here: `Engine::load()` FAILS for this home
    /// (it has no engine `config.toml`), and a failed load still does the
    /// config read and the registry bind the fix removes. Measured on the
    /// pre-fix tree this DELTA is 2 (plan load + dispatch load); with the
    /// fix it is 0.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn review_loads_engine_once() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        // `HomeGuard` takes the process-wide env lock itself; taking it
        // again here would deadlock this test before it measured anything.
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        mount_200_review_with_false_undefined_finding(&server).await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");

        let root_dir = tempfile::tempdir().unwrap();
        let root = root_dir.path();
        std::fs::create_dir_all(root.join("pkg")).unwrap();
        std::fs::write(root.join("pkg/mod.py"), "RETRY_LIMIT = 3\n").unwrap();
        let diff = concat!(
            "diff --git a/pkg/mod.py b/pkg/mod.py\n",
            "index 1111111..2222222 100644\n",
            "--- a/pkg/mod.py\n",
            "+++ b/pkg/mod.py\n",
            "@@ -1,2 +1,3 @@\n",
            " RETRY_LIMIT = 3\n",
            "+RETRY_LIMIT_UNUSED = 4\n"
        );
        let cli = review_cli();

        // One engine for the fixture, loaded OUTSIDE the measured window.
        let eng = test_engine();

        let before = crate::engine_load_count_for(home);
        let _ = run_loop_review_once(
            &cli,
            &eng,
            None,
            &[],
            &[],
            "review the diff",
            diff,
            "working tree",
            "",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            root,
        )
        .await
        .expect("the loop review completes against the mock reviewer");
        let delta = crate::engine_load_count_for(home) - before;

        // The review dispatches one chunk through one candidate: the only
        // load it may add is zero — every path now borrows the engine the
        // caller loaded. Pre-fix this was 2 (plan load + dispatch load).
        assert_eq!(
            delta, 0,
            "a review must not reload the engine; it borrowed &Engine but the count rose by {delta}"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_pool_fails_over_only_to_verified_healthy_secondary() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(503).set_body_string("primary unavailable"))
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;
        write_corpus(
            home,
            &[
                "broken-model/coder",
                "broken-model/reviewer",
                "working-model/reviewer",
            ],
        );
        write_config(
            home,
            &server.uri(),
            "broken-model/reviewer,working-model/reviewer",
        );
        let mut cli = Cli::try_parse_from([
            "zoder", "exec", "-m", "broken-model/coder", "--retries", "0",
            "--allowed-routes", "wiremock-broken=broken-model/coder,wiremock-broken=broken-model/reviewer,wiremock-working=working-model/reviewer",
            "--reviewer-allowed-routes", "wiremock-broken=broken-model/reviewer,wiremock-working=working-model/reviewer",
            "--reviewer-pool-routes", "wiremock-working=working-model/reviewer",
        ]).unwrap();
        assert_eq!(
            build_reviewer_candidates(&cli, None, &[], None).unwrap(),
            ["broken-model/reviewer"]
        );
        HealthStore::mutate_locked(&home.join("health.json"), |health| {
            health.record_classified_success(
                "working-model/reviewer",
                100.0,
                "wiremock-working",
                zoder_core::Classification::Reachable,
            );
        })
        .unwrap();
        assert_eq!(
            build_reviewer_candidates(&cli, None, &[], None).unwrap(),
            ["broken-model/reviewer", "working-model/reviewer"]
        );
        cli.no_fallback = true;
        assert_eq!(
            build_reviewer_candidates(&cli, None, &[], None).unwrap(),
            ["broken-model/reviewer"]
        );
        cli.no_fallback = false;
        let completion = complete_once(&cli, None, &[], "system", "review", 1024, None)
            .await
            .unwrap();
        assert_eq!(completion.model, "working-model/reviewer");
        let health = HealthStore::load(&home.join("health.json"));
        assert_eq!(
            health.models["broken-model/reviewer"].classification,
            Some(zoder_core::Classification::Capacity)
        );
        assert_eq!(
            health.models["working-model/reviewer"].classification,
            Some(zoder_core::Classification::Reachable)
        );
        for request in server.received_requests().await.unwrap() {
            let body: serde_json::Value = serde_json::from_slice(&request.body).unwrap();
            assert_ne!(body["model"], "broken-model/coder");
        }
        HealthStore::mutate_locked(&home.join("health.json"), |health| {
            health.record_classified_failure(
                "working-model/reviewer",
                "503",
                "wiremock-working",
                zoder_core::Classification::Capacity,
            );
        })
        .unwrap();
        assert_eq!(
            build_reviewer_candidates(&cli, None, &[], None).unwrap(),
            ["broken-model/reviewer"]
        );
        assert!(
            complete_once(&cli, None, &[], "system", "review", 1024, None)
                .await
                .is_err()
        );
        assert_eq!(
            server
                .received_requests()
                .await
                .unwrap()
                .iter()
                .filter(|request| request.url.path().contains("/working/"))
                .count(),
            1,
            "an unhealthy pool must not reuse its secondary or escape to another route"
        );
        cli.reviewer_allowed_routes = cli.allowed_routes.clone();
        cli.reviewer_pool_routes = Some("wiremock-broken=broken-model/coder".into());
        assert!(build_reviewer_candidates(&cli, None, &[], None)
            .unwrap_err()
            .to_string()
            .contains("author route"));
        cli.reviewer_pool_routes = Some("wiremock-broken=broken-model/reviewer".into());
        assert!(build_reviewer_candidates(&cli, None, &[], None)
            .unwrap_err()
            .to_string()
            .contains("primary reviewer"));
        cli.reviewer_allowed_routes = None;
        assert!(build_reviewer_candidates(&cli, None, &[], None)
            .unwrap_err()
            .to_string()
            .contains("requires --reviewer-allowed-routes"));
    }

    // ---- Task H: author-family-aware reviewer chain ---------------------

    /// A runtime-derived, no-literal base URL: bind a listener to the
    /// loopback interface on an ephemeral port and assemble the URL from the
    /// bound address. The plan tests never dispatch, so the listener only
    /// supplies a valid loopback host/port for the configured providers.
    fn runtime_loopback_uri() -> String {
        let listener = std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST, 0)).unwrap();
        let addr = listener.local_addr().unwrap();
        format!("http://{}", addr)
    }

    /// FINDING 3 regression: the family filter must run on the PRODUCTION
    /// path, not just the direct helper. This test drives
    /// `complete_review_chunks` -> `complete_once_tracked` ->
    /// `build_reviewer_plan` (the production call site at
    /// `complete_once_tracked`, line ~814) with LOOP author models, and
    /// proves a same-family candidate is SKIPPED BEFORE DISPATCH: the
    /// configured head reviewer is in the author family, so the chain
    /// must fall through to the cross-family tail, and the skip record
    /// must name `family_excluded`. If the production call to
    /// `build_reviewer_plan` inside `complete_once_tracked` were removed,
    /// the head candidate would dispatch (or the plan would be empty
    /// without a skip trail) and this test fails.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn production_review_path_skips_same_family_candidate_before_dispatch() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        // The head (same-family) reviewer must NEVER be dispatched: its
        // route is mounted with a 500 that names the violation if hit.
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(
                ResponseTemplate::new(500)
                    .set_body_string("same-family reviewer must not be dispatched"),
            )
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;
        write_corpus(
            home,
            &[
                "broken-model/coder",
                "broken-model/reviewer",
                "working-model/reviewer",
            ],
        );
        // Configured chain: same-family head first, cross-family tail second.
        write_config(
            home,
            &server.uri(),
            "broken-model/reviewer,working-model/reviewer",
        );
        write_model_families(
            home,
            json!({
                "broken-model/*": "family-a",
                "working-model/*": "family-b",
            }),
        );
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        // LOOP author models: the code under review was authored by a
        // `broken-model` family member.
        let author_models: Vec<String> = vec!["broken-model/coder".to_string()];
        let (completion, report) = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            None,
            &[],
            &author_models,
            REVIEW_SYSTEM,
            &["diff".into()],
            2048,
            None,
            &|_| None,
        )
        .await
        .expect("the cross-family tail must review after the same-family head is excluded");
        assert_eq!(
            completion.model, "working-model/reviewer",
            "the cross-family tail must serve the review, not the same-family head"
        );
        assert_eq!(
            report.served_model.as_deref(),
            Some("working-model/reviewer"),
            "the report must record the model that actually served the review"
        );
        assert_eq!(
            report.requested_model.as_deref(),
            Some("working-model/reviewer"),
            "a same-family head is never requested; the cross-family tail is"
        );
        assert!(
            report
                .skipped
                .iter()
                .any(|s| s.model == "broken-model/reviewer" && s.reason == "family_excluded"),
            "the same-family head must be recorded as skipped BEFORE dispatch: {:?}",
            report.skipped
        );
        // The same-family reviewer was never dispatched.
        let hit_broken = server
            .received_requests()
            .await
            .unwrap()
            .iter()
            .any(|r| r.url.path().contains("/broken/"));
        assert!(
            !hit_broken,
            "the same-family reviewer must not receive a dispatch"
        );
    }

    #[test]
    fn author_family_excludes_configured_chain_pin_and_pool() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        write_corpus(
            home,
            &[
                "broken-model/coder",
                "broken-model/reviewer",
                "working-model/other",
            ],
        );
        write_config(
            home,
            &runtime_loopback_uri(),
            "broken-model/reviewer,working-model/other",
        );
        write_model_families(
            home,
            json!({
                "broken-model/*": "family-a",
                "working-model/*": "family-b",
            }),
        );
        let authors = vec!["broken-model/coder".to_string()];

        // Configured chain: the same-family reviewer is dropped, the
        // cross-family tail remains, and the skip is recorded.
        let cli = Cli::try_parse_from(["zoder", "review"]).unwrap();
        let plan = build_reviewer_plan(&cli, &test_engine(), None, &[], &authors).unwrap();
        assert_eq!(plan.candidates, vec!["working-model/other"]);
        assert_eq!(plan.author_families, vec!["family-a"]);
        assert!(plan
            .skipped
            .iter()
            .any(|s| { s.model == "broken-model/reviewer" && s.reason == "family_excluded" }));

        // Explicit operator pin: kept, flagged, and warned about — not
        // silently dropped.
        let pinned = build_reviewer_plan(
            &cli,
            &test_engine(),
            Some("broken-model/reviewer"),
            &[],
            &authors,
        )
        .unwrap();
        assert!(pinned.forced, "an explicit same-family pin must be flagged");
        assert_eq!(
            pinned.candidates.first().map(String::as_str),
            Some("broken-model/reviewer"),
            "the explicit pin must head the chain even when forced"
        );
        assert!(
            !pinned
                .candidates
                .contains(&"working-model/other".to_string())
                || pinned
                    .candidates
                    .iter()
                    .filter(|m| *m == "working-model/other")
                    .count()
                    == 1,
            "the cross-family tail remains available as a fallback"
        );

        // Verified secondary pool: a same-family pool member is filtered
        // just like a configured candidate.
        HealthStore::mutate_locked(&home.join("health.json"), |health| {
            health.record_classified_success(
                "working-model/other",
                100.0,
                "wiremock-working",
                zoder_core::Classification::Reachable,
            );
        })
        .unwrap();
        let pool_cli = Cli::try_parse_from([
            "zoder",
            "review",
            "-m",
            "broken-model/coder",
            "--allowed-routes",
            "wiremock-broken=broken-model/coder,wiremock-broken=broken-model/reviewer,wiremock-working=working-model/other",
            "--reviewer-allowed-routes",
            "wiremock-broken=broken-model/reviewer,wiremock-working=working-model/other",
            "--reviewer-pool-routes",
            "wiremock-working=working-model/other",
        ])
        .unwrap();
        let pooled = build_reviewer_plan(&pool_cli, &test_engine(), None, &[], &authors).unwrap();
        assert_eq!(pooled.candidates, vec!["working-model/other"]);
        assert!(pooled
            .skipped
            .iter()
            .any(|s| s.model == "broken-model/reviewer" && s.reason == "family_excluded"));
    }

