    /// F2.4: the reset hint must survive the reviewer fallback. `FallbackWorthy`
    /// used to carry only message/kind/status, so a 429 from any non-MiniMax
    /// provider reached the health store with no reset time and other workers
    /// kept re-dialling an endpoint that was still rate-limited.
    #[test]
    fn fallback_worthy_keeps_reset_hint() {
        let resets_at: DateTime<Utc> = "2026-11-02T05:00:00Z".parse().unwrap();
        let err = zoder_core::ProviderError {
            message: "provider HTTP 429: too many requests".into(),
            kind: zoder_core::ErrKind::RateLimit,
            status: Some(429),
            retry_after: Some(Duration::from_secs(45)),
            token_plan_resets_at: Some(resets_at),
            ..Default::default()
        };
        match ReviewerError::fallback_worthy_from(err) {
            ReviewerError::FallbackWorthy {
                retry_after,
                token_plan_resets_at,
                ..
            } => {
                assert_eq!(retry_after, Some(Duration::from_secs(45)));
                assert_eq!(token_plan_resets_at, Some(resets_at));
            }
            other => panic!("a provider error must stay fallback-worthy, got {other:?}"),
        }
    }

    /// F2.4: for a provider that is not MiniMax there is no plan observation to
    /// read, so the wall has to come from the error itself.
    #[test]
    fn fallback_reset_wall_uses_retry_after_for_non_minimax_providers() {
        let now: DateTime<Utc> = "2026-11-02T04:00:00Z".parse().unwrap();
        assert_eq!(
            fallback_reset_wall_from(
                Some(429),
                Some(Duration::from_secs(45)),
                None,
                "openai-direct",
                now
            ),
            Some((now + chrono::Duration::seconds(45)).timestamp())
        );
        // A status-less failure (Anthropic's SSE overload, a bare 400) still
        // gets the Retry-After the transport carried.
        assert_eq!(
            fallback_reset_wall_from(None, Some(Duration::from_secs(30)), None, "gw", now),
            Some((now + chrono::Duration::seconds(30)).timestamp())
        );
    }

    /// F2.4: an explicit plan reset beats an inferred Retry-After, and neither
    /// present leaves the old behaviour (MiniMax observation on a 429) intact.
    #[test]
    fn fallback_reset_wall_prefers_plan_reset_and_keeps_no_wall_without_a_hint() {
        let now: DateTime<Utc> = "2026-11-02T04:00:00Z".parse().unwrap();
        let plan_reset: DateTime<Utc> = "2026-11-02T06:00:00Z".parse().unwrap();
        assert_eq!(
            fallback_reset_wall_from(
                Some(429),
                Some(Duration::from_secs(45)),
                Some(plan_reset),
                "minimax",
                now
            ),
            Some(plan_reset.timestamp())
        );
        assert_eq!(
            fallback_reset_wall_from(Some(500), None, None, "no-state-provider", now),
            None
        );
    }

    /// F2.5: a provider error BODY can name a parameter called
    /// `stream_timeout` without the call having timed out. `skipped[].reason`
    /// is what an operator triages from, so it must not report "timeout" for
    /// a 400 that says the parameter is unsupported.
    #[test]
    fn skip_reason_does_not_match_timeout_inside_error_body() {
        assert_eq!(
            reviewer_skip_reason(
                zoder_core::ErrKind::Http,
                "provider HTTP 400: {\"error\":\"unsupported parameter: stream_timeout\"}"
            ),
            "unavailable"
        );
        // The transport-level wording before any body still reads as a timeout.
        assert_eq!(
            reviewer_skip_reason(
                zoder_core::ErrKind::Http,
                "provider HTTP 504: upstream timed out"
            ),
            "timeout"
        );
    }

    #[test]
    fn reviewer_skip_reason_distinguishes_timeout_from_unavailable() {
        assert_eq!(
            reviewer_skip_reason(zoder_core::ErrKind::Timeout, "request deadline"),
            "timeout"
        );
        assert_eq!(
            reviewer_skip_reason(zoder_core::ErrKind::Http, "provider HTTP 503"),
            "unavailable"
        );
        assert_eq!(
            reviewer_skip_reason(zoder_core::ErrKind::Network, "connect timed out"),
            "timeout"
        );
    }

    #[test]
    fn high_risk_paths_are_globs_over_the_changed_files() {
        let diff = "diff --git a/src/security/auth.rs b/src/security/auth.rs\n\
--- a/src/security/auth.rs\n\
+++ b/src/security/auth.rs\n\
@@ -1 +1 @@\n\
-old\n\
+new\n";
        assert_eq!(diff_changed_paths(diff), vec!["src/security/auth.rs"]);
        let cfg = zoder_core::config::ReviewConfig {
            escalate: zoder_core::config::ReviewEscalateConfig {
                paths: vec!["src/security/**".into()],
            },
            ..Default::default()
        };
        assert!(cfg
            .escalate
            .paths
            .iter()
            .any(|pattern| crate::review_diff::glob_match(pattern, "src/security/auth.rs")));
        assert!(!crate::review_diff::glob_match(
            "src/security/**",
            "src/lib.rs"
        ));
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn high_risk_glob_requires_a_second_non_local_reviewer() {
        // F3.1: reaching the local mock while classifying as HOSTED needs the
        // IPv4-mapped IPv6 literal below — `is_local_route` treats all of
        // 127/8 as local, so no plain IPv4 address can stand in. A runner
        // without IPv6 sockets cannot run this test at all, so skip instead
        // of turning the whole suite red there.
        if std::net::TcpListener::bind("[::1]:0").is_err() {
            eprintln!(
                "skipping high_risk_glob_requires_a_second_non_local_reviewer: no IPv6 on this host"
            );
            return;
        }
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let local = MockServer::start().await;
        let hosted = MockServer::start().await;
        mount_200_openai_chat_completion(&local).await;
        // The hosted provider's base URL is an IPv4-mapped IPv6 loopback
        // literal: it reaches the local mock while `Provider::is_local_route`
        // classifies it as HOSTED (the route classification is endpoint
        // based, not a name check).
        let hosted_port = hosted.uri().rsplit(':').next().unwrap().to_string();
        Mock::given(method("POST"))
            .and(path("/hosted/v1/chat/completions"))
            .respond_with(
                ResponseTemplate::new(200)
                    .set_body_string(openai_review_completion("hosted reviewer ok")),
            )
            .mount(&hosted)
            .await;
        write_corpus(home, &["local-model/reviewer", "hosted-model/reviewer"]);
        let body = json!({
            "providers": [
                {
                    "id": "wiremock-local",
                    "base_url": format!("{}/local", local.uri()),
                    "kind": "openai-chat",
                    "auth": {"type": "none"},
                    "billing": "free",
                    "serves": ["local-model/"],
                },
                {
                    "id": "wiremock-hosted",
                    "base_url": format!("http://[::ffff:127.0.0.1]:{hosted_port}/hosted"),
                    "kind": "openai-chat",
                    "auth": {"type": "none"},
                    "billing": "free",
                    "serves": ["hosted-model/"],
                },
            ],
            "default_provider": "wiremock-local",
            "strict_free": false,
            "corpus_path": home.join("model_corpus.json"),
            "ledger_path": home.join("ledger.jsonl"),
            "health_path": home.join("health.json"),
            "reviewer_model": "local-model/reviewer,hosted-model/reviewer",
        });
        std::fs::write(
            home.join("config.json"),
            serde_json::to_string_pretty(&body).unwrap(),
        )
        .unwrap();
        // The LOCAL provider needs the local path; the shared helper mounts
        // `/working`, so mount the local model explicitly.
        Mock::given(method("POST"))
            .and(path("/local/v1/chat/completions"))
            .respond_with(
                ResponseTemplate::new(200)
                    .set_body_string(openai_review_completion("local reviewer ok")),
            )
            .mount(&local)
            .await;
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let cfg = zoder_core::config::ReviewConfig {
            escalate: zoder_core::config::ReviewEscalateConfig {
                paths: vec!["src/security/**".into()],
            },
            ..Default::default()
        };
        let diff = "diff --git a/src/security/auth.rs b/src/security/auth.rs\n\
--- a/src/security/auth.rs\n\
+++ b/src/security/auth.rs\n\
@@ -1 +1 @@\n\
-old\n\
+new\n";
        let (review, _model, _cost, _chunks, verdicts) = run_loop_review(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            ADVERSARIAL_SYSTEM,
            diff,
            "branch",
            "task\n",
            Some("local-model/reviewer"),
            Some(&cfg),
            &[],
            &[],
            home,
        )
        .await
        .expect("a high-risk diff must review on both reviewers");
        assert_eq!(verdicts.len(), 2, "high risk requires a second reviewer");
        assert_eq!(
            verdicts[1]["escalation_reason"].as_str(),
            Some("high_risk"),
            "{verdicts:?}"
        );
        assert_eq!(verdicts[1]["high_risk_reviewer"].as_bool(), Some(true));
        assert_eq!(
            review.escalation_reason.as_deref(),
            Some("high_risk"),
            "the aggregate verdict must record why the second reviewer ran"
        );
        assert_eq!(
            hosted
                .received_requests()
                .await
                .unwrap()
                .iter()
                .filter(|r| r.url.path().contains("/hosted/"))
                .count(),
            1,
            "the non-local candidate must be the second reviewer"
        );
    }

