    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn cmd_route_regression_valid_and_impossible_allowlists() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        write_corpus(home, &["broken-model/head", "working-model/reviewer"]);
        write_config(home, &runtime_loopback_uri(), "working-model/reviewer");

        // Valid CLI parse
        let cli = Cli::try_parse_from([
            "zoder",
            "route",
            "--model",
            "broken-model/head",
            "--allowed-routes",
            "wiremock-broken=broken-model/head,wiremock-working=working-model/reviewer",
            "--dry-run",
            "--json",
        ])
        .unwrap();

        // crate::cmd_route(&cli, None).await must succeed
        crate::cmd_route(&cli, None)
            .await
            .expect("cmd_route should succeed for valid allowlist");

        // Check crate::resolve_chain with Engine::load and HealthStore::default
        let engine = Engine::load().expect("engine load");
        let health_store = HealthStore::default();
        let chain = crate::resolve_chain(&cli, &engine, &health_store)
            .expect("resolve_chain should succeed");

        // build_reviewer_candidates returns includes configured working reviewer
        let candidates = build_reviewer_candidates(&cli, None, &chain.reviewer, None)
            .expect("build_reviewer_candidates should succeed");
        assert!(
            candidates.contains(&"working-model/reviewer".to_string()),
            "candidates should include working-model/reviewer"
        );

        // Impossible parse allowlist
        let cli_impossible = Cli::try_parse_from([
            "zoder",
            "route",
            "--model",
            "broken-model/head",
            "--allowed-routes",
            "no-such-provider=not-a-model",
            "--dry-run",
            "--json",
        ])
        .unwrap();

        let result = crate::cmd_route(&cli_impossible, None).await;
        assert!(
            result.is_err(),
            "cmd_route should fail for impossible allowlist"
        );
        let err_msg = result.unwrap_err().to_string();
        assert!(
            err_msg.contains("no author route matches"),
            "error should contain 'no author route matches', got: {}",
            err_msg
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_allowlist_prevents_tail_after_failure() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        let broken_hits = Arc::new(AtomicUsize::new(0));
        let broken_hits_for_responder = Arc::clone(&broken_hits);
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(move |_: &wiremock::Request| {
                broken_hits_for_responder.fetch_add(1, Ordering::SeqCst);
                ResponseTemplate::new(404).set_body_string(r#"{"error": "model not found"}"#)
            })
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli = Cli::try_parse_from([
            "zoder",
            "exec",
            "--request-timeout",
            "1",
            "--retries",
            "0",
            "--allowed-routes",
            "wiremock-broken=broken-model/coder-6.7b,wiremock-working=working-model/glm-5.1",
            "--reviewer-allowed-routes",
            "wiremock-broken=broken-model/coder-6.7b",
        ])
        .expect("clap parse");
        let result = complete_once(
            &cli,
            Some("broken-model/coder-6.7b"),
            &[],
            "sys",
            "user",
            2048,
            None,
        )
        .await;

        assert!(
            result.is_err(),
            "expected error due to permanent failure on head and tail exclusion by allowlist"
        );

        let requests = server.received_requests().await.unwrap_or_default();
        let paths: Vec<String> = requests.iter().map(|r| r.url.path().to_string()).collect();
        assert!(
            paths.iter().filter(|p| p.contains("/broken/")).count() > 0,
            "broken head must be attempted: paths={paths:?}"
        );
        assert_eq!(
            paths.iter().filter(|p| p.contains("/working/")).count(),
            0,
            "working tail must not be attempted due to allowlist exclusion: paths={paths:?}"
        );
        assert!(broken_hits.load(Ordering::SeqCst) > 0);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_retries_timeout_on_same_model_before_trying_tail() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        let broken_hits = Arc::new(AtomicUsize::new(0));
        let broken_hits_for_responder = Arc::clone(&broken_hits);
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(move |_: &wiremock::Request| {
                let attempt = broken_hits_for_responder.fetch_add(1, Ordering::SeqCst);
                if attempt == 0 {
                    ResponseTemplate::new(200)
                        .set_delay(Duration::from_secs(2))
                        .set_body_string(openai_review_completion("head was too slow"))
                } else {
                    ResponseTemplate::new(200)
                        .set_body_string(openai_review_completion("head retry ok"))
                }
            })
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli =
            Cli::try_parse_from(["zoder", "exec", "--request-timeout", "1", "--retries", "1"])
                .expect("clap parse");
        let c = complete_once(&cli, None, &[], "sys", "user", 2048, None)
            .await
            .expect("same reviewer model should be retried before fallback");
        assert_eq!(
            c.model, "broken-model/coder-6.7b",
            "the head should win after a same-model retry"
        );
        assert!(
            c.content.contains("head retry ok"),
            "retry response should be surfaced; got: {}",
            c.content
        );
        let requests = server.received_requests().await.unwrap_or_default();
        let paths: Vec<String> = requests.iter().map(|r| r.url.path().to_string()).collect();
        assert_eq!(
            paths.iter().filter(|p| p.contains("/broken/")).count(),
            2,
            "head must be tried twice: paths={paths:?}"
        );
        assert_eq!(
            paths.iter().filter(|p| p.contains("/working/")).count(),
            0,
            "tail must not be tried after the head succeeds on retry: paths={paths:?}"
        );
        assert_eq!(broken_hits.load(Ordering::SeqCst), 2);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_single_503_without_retries_does_not_fallback_to_tail() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(503).set_body_string("queue full"))
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).expect("clap parse");
        let err = complete_once(&cli, None, &[], "sys", "user", 2048, None)
            .await
            .expect_err("a single 503 is transient, not model-unavailable fallback");
        let msg = format!("{err:#}");
        assert!(
            msg.contains("503") || msg.to_lowercase().contains("queue full"),
            "the transient 503 must be surfaced for retry/tuning, not hidden: {msg}"
        );
        let requests = server.received_requests().await.unwrap_or_default();
        let paths: Vec<String> = requests.iter().map(|r| r.url.path().to_string()).collect();
        assert_eq!(
            paths.iter().filter(|p| p.contains("/broken/")).count(),
            1,
            "head should be tried once when retries are disabled: paths={paths:?}"
        );
        assert_eq!(
            paths.iter().filter(|p| p.contains("/working/")).count(),
            0,
            "tail should not be tried for a single transient 503: paths={paths:?}"
        );
    }

    /// Per-route chunking: when the first chunk is served by a different
    /// model than the plan was sized for, the review re-plans for the serving
    /// model (once) and reviews every one of ITS chunks with it.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn fallback_on_first_chunk_replans_chunks_for_the_serving_model() {
        let dir = tempfile::tempdir().unwrap();
        let _guard = HomeGuard::new(dir.path());
        let server = MockServer::start().await;
        let hits = Arc::new(AtomicUsize::new(0));
        let counter = hits.clone();
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(move |_: &wiremock::Request| {
                counter.fetch_add(1, Ordering::SeqCst);
                ResponseTemplate::new(200).set_body_json(json!({"choices":[{"message":{"content":
                    r#"{"verdict":"approve","summary":"No defects in the supplied diff.","findings":[],"next_steps":[]}"#
                },"finish_reason":"stop"}]}))
            })
            .mount(&server)
            .await;
        write_corpus(dir.path(), &["working-model/glm-5.1"]);
        write_config(dir.path(), &server.uri(), "working-model/glm-5.1");
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let replans = AtomicUsize::new(0);
        let replan = |model: &str| -> Option<(Vec<String>, u32)> {
            assert_eq!(model, "working-model/glm-5.1");
            replans.fetch_add(1, Ordering::SeqCst);
            Some((vec!["part a".into(), "part b".into()], 4096))
        };
        let result = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/glm-5.1"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["one big chunk sized for another reviewer".into()],
            2048,
            Some("planned-model/large-chunks".into()),
            &replan,
        )
        .await
        .unwrap()
        .0;
        assert_eq!(result.model, "working-model/glm-5.1");
        assert_eq!(
            result.chunks, 2,
            "the completion must report the RE-PLANNED chunk count, not the initial 1"
        );
        assert_eq!(replans.load(Ordering::SeqCst), 1, "re-plans exactly once");
        // 1 call for the original first chunk + 2 for the re-planned chunks.
        assert_eq!(hits.load(Ordering::SeqCst), 3);
        // The replanned review's report: ONE report for the whole call, and
        // BOTH model identities captured from the re-dispatched first chunk
        // (the replanned model), not from the abandoned pre-replan dispatch.
        let report = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/glm-5.1"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["one big chunk sized for another reviewer".into()],
            2048,
            Some("planned-model/large-chunks".into()),
            &|_| Some((vec!["part a".into(), "part b".into()], 4096)),
        )
        .await
        .unwrap()
        .1;
        assert_eq!(
            report.served_model.as_deref(),
            Some("working-model/glm-5.1"),
            "the report must name the model that served the RE-PLANNED chunks"
        );
        assert_eq!(
            report.requested_model.as_deref(),
            Some("working-model/glm-5.1"),
            "the requested identity must be captured from the same dispatch as the served one"
        );
        assert_eq!(
            report.chunks.len(),
            2,
            "one evidence entry per re-planned chunk"
        );

        // No re-plan when the planned model served the chunk.
        hits.store(0, Ordering::SeqCst);
        let result = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/glm-5.1"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["x".into(), "y".into()],
            2048,
            Some("working-model/glm-5.1".into()),
            &|_| panic!("must not re-plan when the planned reviewer served"),
        )
        .await
        .unwrap()
        .0;
        assert_eq!(result.model, "working-model/glm-5.1");
        assert_eq!(result.chunks, 2, "no re-plan: the plan's chunk count");
        assert_eq!(hits.load(Ordering::SeqCst), 2);
    }

    /// Config with a gated provider (id `provider-a`) and a working
    /// fallback, reviewer chain gated provider first.
    fn write_gated_config(home: &Path, mock_uri: &str, reviewer_model: &str) {
        let body = serde_json::json!({
            "providers": [
                {
                    "id": "provider-a",
                    "base_url": format!("{mock_uri}/provider-a"),
                    "kind": "openai-chat",
                    "auth": {"type": "none"},
                    "billing": "free",
                    "serves": ["gated-model/"],
                },
                {
                    "id": "wiremock-working",
                    "base_url": format!("{mock_uri}/working"),
                    "kind": "openai-chat",
                    "auth": {"type": "none"},
                    "billing": "free",
                    "serves": ["working-model/"],
                },
            ],
            "default_provider": "wiremock-working",
            "health": {"providers": ["provider-a"]},
            "strict_free": false,
            "corpus_path": home.join("model_corpus.json"),
            "ledger_path": home.join("ledger.jsonl"),
            "health_path": home.join("health.json"),
            "reviewer_model": reviewer_model,
        });
        std::fs::write(
            home.join("config.json"),
            serde_json::to_string_pretty(&body).unwrap(),
        )
        .unwrap();
    }

    const APPROVE_VERDICT: &str = r#"{"verdict":"approve","summary":"No defects in the supplied diff.","findings":[],"next_steps":[]}"#;

    fn approve_response() -> ResponseTemplate {
        ResponseTemplate::new(200).set_body_json(json!({
            "choices":[{"message":{"content":APPROVE_VERDICT},"finish_reason":"stop"}]
        }))
    }

    async fn mount_working(server: &MockServer) {
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(approve_response())
            .mount(server)
            .await;
    }

    fn gate_of(home: &Path, model: &str) -> Option<zoder_core::health::PreQueryGate> {
        HealthStore::load(&home.join("health.json"))
            .models
            .get(model)
            .and_then(|m| m.gate.clone())
    }

    /// Provider health gate: a probe precedes the first query, a fresh check
    /// is cached, a 429 is not retried in-process but opens the breaker (with
    /// Retry-After) and falls back, and the next run skips the gated provider
    /// without touching it and reports `skipped_unhealthy`.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn provider_health_gate_probes_caches_backs_off_on_429_and_skips() {
        let dir = tempfile::tempdir().unwrap();
        let home = dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        let model_hits = Arc::new(AtomicUsize::new(0));
        let mh = model_hits.clone();
        Mock::given(method("GET"))
            .and(path("/provider-a/v1/models"))
            .respond_with(move |_: &wiremock::Request| {
                mh.fetch_add(1, Ordering::SeqCst);
                ResponseTemplate::new(200)
                    .set_body_json(json!({"data":[{"id":"gated-model/reviewer"},{"id":"other"}]}))
            })
            .mount(&server)
            .await;
        let chat_hits = Arc::new(AtomicUsize::new(0));
        let ch = chat_hits.clone();
        Mock::given(method("POST"))
            .and(path("/provider-a/v1/chat/completions"))
            .respond_with(move |_: &wiremock::Request| {
                if ch.fetch_add(1, Ordering::SeqCst) < 2 {
                    approve_response()
                } else {
                    ResponseTemplate::new(429)
                        .insert_header("retry-after", "45")
                        .set_body_string("rate limited")
                }
            })
            .mount(&server)
            .await;
        mount_working(&server).await;
        write_corpus(home, &["gated-model/reviewer", "working-model/reviewer"]);
        write_gated_config(
            home,
            &server.uri(),
            "gated-model/reviewer,working-model/reviewer",
        );
        let cli = Cli::try_parse_from(["zoder", "review", "--retries", "2"]).unwrap();
        let _ = crate::provider_health::take_skipped();

        let first = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(first.model, "gated-model/reviewer");
        assert_eq!(first.receipts[0]["health"]["source"], "probe");
        assert_eq!(model_hits.load(Ordering::SeqCst), 1);

        let second = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(second.receipts[0]["health"]["source"], "cache");
        assert_eq!(
            model_hits.load(Ordering::SeqCst),
            1,
            "fresh check is cached"
        );

        // 429: exactly one chat attempt (no in-process retry), breaker open
        // for at least Retry-After, review served by the fallback.
        let before = chat_hits.load(Ordering::SeqCst);
        // T1-4: Retry-After is 45 s, and the breaker is stamped `now + 45` when
        // the 429 arrives. Compare against the moment BEFORE the request, not
        // against a fresh `now` after it: a slow or contended worker spends
        // seconds between the two and the old `now + 40` edge flaked.
        let request_started_at = chrono::Utc::now().timestamp();
        let third = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(third.model, "working-model/reviewer");
        assert_eq!(
            chat_hits.load(Ordering::SeqCst),
            before + 1,
            "no retry into a 429"
        );
        let gate = gate_of(home, "gated-model/reviewer").expect("breaker opened");
        assert_eq!(gate.open_count, 1);
        assert!(
            gate.retry_not_before_unix.unwrap() >= request_started_at + 45,
            "the breaker must stay open for the full Retry-After"
        );

        // Next run: skipped without any gated request, reported, never a pass.
        let (m0, c0) = (
            model_hits.load(Ordering::SeqCst),
            chat_hits.load(Ordering::SeqCst),
        );
        let fourth = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(fourth.model, "working-model/reviewer");
        assert_eq!(model_hits.load(Ordering::SeqCst), m0);
        assert_eq!(chat_hits.load(Ordering::SeqCst), c0);
        let skipped = crate::provider_health::take_skipped();
        assert_eq!(skipped.len(), 1, "{skipped:?}");
        assert_eq!(skipped[0]["model"], "gated-model/reviewer");
        assert_eq!(skipped[0]["provider"], "provider-a");
        assert!(skipped[0]["reason"].as_str().unwrap().contains("429"));
    }

    /// A failing probe (503) skips the gated provider with backoff; once the
    /// backoff has elapsed a single half-open probe runs, succeeds, and
    /// closes the gate.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn provider_health_gate_backs_off_on_503_probe_then_recovers_half_open() {
        let dir = tempfile::tempdir().unwrap();
        let home = dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        let model_hits = Arc::new(AtomicUsize::new(0));
        let mh = model_hits.clone();
        Mock::given(method("GET"))
            .and(path("/provider-a/v1/models"))
            .respond_with(move |_: &wiremock::Request| {
                if mh.fetch_add(1, Ordering::SeqCst) == 0 {
                    ResponseTemplate::new(503).set_body_string("unavailable")
                } else {
                    ResponseTemplate::new(200)
                        .set_body_json(json!({"data":[{"id":"gated-model/reviewer"}]}))
                }
            })
            .mount(&server)
            .await;
        Mock::given(method("POST"))
            .and(path("/provider-a/v1/chat/completions"))
            .respond_with(approve_response())
            .mount(&server)
            .await;
        mount_working(&server).await;
        write_corpus(home, &["gated-model/reviewer", "working-model/reviewer"]);
        write_gated_config(
            home,
            &server.uri(),
            "gated-model/reviewer,working-model/reviewer",
        );
        let cli = Cli::try_parse_from(["zoder", "review", "--retries", "0"]).unwrap();
        let _ = crate::provider_health::take_skipped();

        let first = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(first.model, "working-model/reviewer");
        let gate = gate_of(home, "gated-model/reviewer").expect("probe failure opens the gate");
        assert_eq!(gate.open_count, 1);
        assert_eq!(crate::provider_health::take_skipped().len(), 1);

        // Simulate the backoff elapsing.
        HealthStore::mutate_locked(&home.join("health.json"), |h| {
            let g = h
                .models
                .get_mut("gated-model/reviewer")
                .unwrap()
                .gate
                .as_mut()
                .unwrap();
            g.retry_not_before_unix = Some(chrono::Utc::now().timestamp() - 1);
        })
        .unwrap();
        let second = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None)
            .await
            .unwrap();
        assert_eq!(second.model, "gated-model/reviewer");
        assert_eq!(second.receipts[0]["health"]["source"], "half_open_probe");
        assert!(
            gate_of(home, "gated-model/reviewer").is_none(),
            "success closes the gate"
        );
        assert_eq!(model_hits.load(Ordering::SeqCst), 2);
    }

    /// A slow probe is bounded and treated as unhealthy; with no fallback the
    /// review fails (a skipped reviewer is never a pass).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn provider_health_gate_bounds_a_slow_probe_and_never_passes_without_fallback() {
        let dir = tempfile::tempdir().unwrap();
        let home = dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("GET"))
            .and(path("/provider-a/v1/models"))
            .respond_with(
                ResponseTemplate::new(200)
                    .set_delay(std::time::Duration::from_secs(3))
                    .set_body_json(json!({"data":[{"id":"gated-model/reviewer"}]})),
            )
            .mount(&server)
            .await;
        write_corpus(home, &["gated-model/reviewer"]);
        write_gated_config(home, &server.uri(), "gated-model/reviewer");
        let cli =
            Cli::try_parse_from(["zoder", "review", "--retries", "0", "--no-fallback"]).unwrap();
        let _ = crate::provider_health::take_skipped();
        crate::provider_health::PROBE_TIMEOUT_OVERRIDE_MS.store(200, Ordering::SeqCst);
        let started = std::time::Instant::now();
        let result = complete_once(&cli, None, &[], REVIEW_SYSTEM, "diff", 2048, None).await;
        crate::provider_health::PROBE_TIMEOUT_OVERRIDE_MS.store(0, Ordering::SeqCst);
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("skipped unhealthy provider model gated-model/reviewer"),
            "{err}"
        );
        assert!(err.contains("timed out"), "{err}");
        assert!(started.elapsed() < std::time::Duration::from_secs(3));
        assert!(gate_of(home, "gated-model/reviewer").is_some());
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn chunk_json_retry_is_bounded_and_never_accepts_schema_echo() {
        for repaired in [false, true] {
            let dir = tempfile::tempdir().unwrap();
            let _guard = HomeGuard::new(dir.path());
            let server = MockServer::start().await;
            let hits = Arc::new(AtomicUsize::new(0));
            let counter = hits.clone();
            Mock::given(method("POST"))
                .and(path("/working/v1/chat/completions"))
                .respond_with(move |_: &wiremock::Request| {
                    let n = counter.fetch_add(1, Ordering::SeqCst);
                    let answer = if repaired && n == 1 {
                        r#"{"verdict":"approve","summary":"No defects in the supplied diff.","findings":[],"next_steps":[]}"#
                    } else { r#"Example schema: {"verdict":"approve"}"# };
                    ResponseTemplate::new(200).set_body_json(json!({"choices":[{"message":{"content":answer},"finish_reason":"stop"}]}))
                }).mount(&server).await;
            write_corpus(dir.path(), &["working-model/glm-5.1"]);
            write_config(dir.path(), &server.uri(), "working-model/glm-5.1");
            let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
            let result = complete_review_chunks(
                &cli,
                Some(&test_engine()),
                Some("working-model/glm-5.1"),
                &[],
                &[],
                REVIEW_SYSTEM,
                &["diff".into()],
                2048,
                None,
                &|_| None,
            )
            .await;
            assert_eq!(result.is_ok(), repaired, "{result:?}");
            assert_eq!(hits.load(Ordering::SeqCst), 2);
            if let Ok((c, _report)) = result {
                assert_eq!(strict_review(&c.content).unwrap().verdict, "approve");
            }
        }
    }

