    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_persistent_5xx_falls_through_after_same_model_retries() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/broken/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(503).set_body_string("backend unavailable"))
            .mount(&server)
            .await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "1"]).expect("clap parse");
        let c = complete_once(&cli, None, &[], "sys", "user", 2048, None)
            .await
            .expect("persistent 5xx should fall through after retrying the same model");
        assert_eq!(
            c.model, "working-model/glm-5.1",
            "persistent 5xx should move to the next reviewer after same-model retries"
        );
        let requests = server.received_requests().await.unwrap_or_default();
        let paths: Vec<String> = requests.iter().map(|r| r.url.path().to_string()).collect();
        assert_eq!(
            paths.iter().filter(|p| p.contains("/broken/")).count(),
            2,
            "head must be retried before fallback: paths={paths:?}"
        );
        assert_eq!(
            paths.iter().filter(|p| p.contains("/working/")).count(),
            1,
            "tail should answer only after the persistent 5xx: paths={paths:?}"
        );
    }

    /// **REGRESSION: 2026-09-15 reviewer-alias-as-wire-model fix.**
    ///
    /// `--reviewer <alias>` (and any other reviewer candidate) may name an
    /// ENGINE AGENT ALIAS (e.g. "reviewer") rather than a literal served-
    /// model-name. `dispatch_reviewer_for_model` used to send that alias
    /// string straight onto the wire as `ChatRequest.model`, which is
    /// correct only when the alias happens to equal the backend's real
    /// served-model-name. Deliberately configure `serves` to contain ONLY
    /// the real checkpoint id ("nemotron35"), never the alias
    /// ("reviewer") itself, so this test fails pre-fix with "no real
    /// provider is configured for reviewer model 'reviewer'" and, if the
    /// wire body were ever un-resolved again, would fail on the wiremock
    /// request-body assertion below instead of silently passing.
    ///
    /// The alias is resolved the same way `--agent`/`-m` already resolve
    /// it for the AUTHOR lane: via the `EngineModelRegistry`
    /// (`[agents.reviewer].model_provider = "custom.reviewer"` ->
    /// `[providers.models.custom.reviewer].model = "nemotron35"`), which
    /// this test writes to `<ZEROCLAW_CONFIG_DIR>/config.toml` alongside
    /// zoder's own `config.json`/corpus in the shared tempdir.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_alias_candidate_resolves_to_real_model_on_the_wire() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        // `Engine::load()` reads the engine (zeroclaw) config from
        // `ZEROCLAW_CONFIG_DIR`'s `config.toml`, a separate file/dir from
        // zoder's own `ZODER_HOME`-relative `config.json`. Both point at
        // this same tempdir's `engine` subdirectory.
        //
        // The engine config path is passed EXPLICITLY to
        // `complete_once` rather than being pushed
        // into the process environment via `ZEROCLAW_CONFIG_DIR`. The env
        // var is process-global shared mutable state: a parallel test
        // that sets it to a different directory would win the race, and
        // this test would then resolve the alias registry from the
        // WRONG engine config — an intermittent failure that looks like
        // a routing bug. See `crate::child_env`.
        let engine_dir = home.join("engine");
        std::fs::create_dir_all(&engine_dir).expect("mkdir engine_dir");
        let engine_config = engine_dir.join("config.toml");
        std::fs::write(
            engine_config.clone(),
            r#"
[providers.models.custom.reviewer]
type = "openai-compatible"
model = "nemotron35"
uri = "https://example.invalid/v1"
chat_template_kwargs = { force_nonempty_content = true }

[agents.reviewer]
model_provider = "custom.reviewer"
"#,
        )
        .expect("write engine config.toml");

        let server = MockServer::start().await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["nemotron35"]);
        // Deliberately `serves: ["nemotron35"]` only — no "reviewer" entry
        // — so provider resolution can succeed ONLY via the alias-to-
        // real-model translation this fix adds, never via a `serves`
        // list that happens to also carry the alias.
        let body = serde_json::json!({
            "providers": [{
                "id": "wiremock-working",
                "base_url": format!("{}/working", server.uri()),
                "kind": "openai-chat",
                "auth": {"type": "none"},
                "billing": "free",
                "serves": ["nemotron35"],
            }],
            "default_provider": "wiremock-working",
            "strict_free": false,
            "corpus_path": home.join("model_corpus.json"),
            "ledger_path": home.join("ledger.jsonl"),
            "health_path": home.join("health.json"),
        });
        std::fs::write(
            home.join("config.json"),
            serde_json::to_string_pretty(&body).unwrap(),
        )
        .unwrap();

        let cli = dummy_cli();
        let c = complete_once(
            &cli,
            Some("reviewer"),
            &[],
            "sys",
            "user",
            2048,
            Some(&engine_config),
        )
        .await
        .expect(
            "an agent-alias reviewer candidate must resolve to its real \
                 model before dispatch, not fail with 'no real provider'",
        );
        assert_eq!(
            c.model, "nemotron35",
            "the reported reviewer model must be the resolved checkpoint id, not the alias"
        );

        let requests = server.received_requests().await.unwrap_or_default();
        assert_eq!(requests.len(), 1, "exactly one dispatch should have fired");
        let sent: serde_json::Value =
            serde_json::from_slice(&requests[0].body).expect("request body is JSON");
        assert_eq!(
            sent.get("model").and_then(|v| v.as_str()),
            Some("nemotron35"),
            "the wire request must carry the real checkpoint id, never the \
             alias — sending the alias verbatim is exactly the 404 this \
             regression pins ('The model `reviewer` does not exist')"
        );
        assert_eq!(
            sent["chat_template_kwargs"]["force_nonempty_content"], true,
            "review dispatch must carry the engine profile's template options"
        );
    }

    /// **REGRESSION: 2026-09-15, corrected same day after a live-fleet
    /// smoke test disproved the first version of this guard.** The first
    /// version of this fix skipped alias resolution for any candidate
    /// that already had a real `[[providers]] serves` entry — which broke
    /// again immediately on the real fleet: `serves` deliberately lists
    /// BOTH an alias ("reviewer") and its live checkpoint ("nemotron35")
    /// per this project's own established convention
    /// (zoder-routing-and-invocation.md #2/#10), so `--reviewer reviewer`
    /// still found a "real provider" for the literal string "reviewer"
    /// and dispatched it verbatim — reproducing the exact 404 this fix
    /// exists to close, through a different route than the original
    /// report. `serves` cannot be used to distinguish "this string is
    /// wire-safe" from "this string is also an alias listed here for
    /// routing convenience only."
    ///
    /// The corrected, narrower guarantee this test pins instead: alias
    /// resolution applies ONLY to operator-written reviewer strings
    /// (`--reviewer`, `[agents.X].reviewer_model`, `Config::reviewer_model`)
    /// — exactly mirroring the author/`--agent` lane, which already
    /// resolves aliases unconditionally with no such gate. The
    /// SCENARIO-ROUTED chain (`reviewer_chain`, sourced entirely from
    /// `eng.corpus`'s real model ids, never an alias) must NEVER be
    /// translated — a scenario-chosen literal model id must dispatch as
    /// itself even when its string happens to collide with an unrelated,
    /// differently-configured agent alias. This is the real, real-fleet
    /// shape: `[agents.nemotron35]` self-references the model
    /// "nemotron35" today, but nothing prevents an alias sharing a
    /// model's name from being repointed at a DIFFERENT model later.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_scenario_chain_literal_is_not_rewritten_by_a_colliding_alias() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        // The engine config path is passed EXPLICITLY (see the sibling
        // test `reviewer_alias_candidate_resolves_to_real_model_on_the_wire`
        // for why `ZEROCLAW_CONFIG_DIR` must not be mutated here).
        let engine_dir = home.join("engine");
        std::fs::create_dir_all(&engine_dir).expect("mkdir engine_dir");
        let engine_config = engine_dir.join("config.toml");
        // An agent alias LITERALLY named "nemotron35" that routes to a
        // DIFFERENT model ("decoy-model") — the collision the fix must
        // not fall into.
        std::fs::write(
            engine_config.clone(),
            r#"
[providers.models.custom.nemotron35]
type = "openai-compatible"
model = "decoy-model"
uri = "https://example.invalid/v1"

[agents.nemotron35]
model_provider = "custom.nemotron35"
"#,
        )
        .expect("write engine config.toml");

        let server = MockServer::start().await;
        mount_200_openai_chat_completion(&server).await;

        // Also list the alias itself in `serves`, matching this project's
        // real convention (and the exact shape that broke the first
        // version of this fix) — proving the guard no longer depends on
        // `serves` excluding the alias.
        write_corpus(&home, &["nemotron35"]);
        let body = serde_json::json!({
            "providers": [{
                "id": "wiremock-working",
                "base_url": format!("{}/working", server.uri()),
                "kind": "openai-chat",
                "auth": {"type": "none"},
                "billing": "free",
                "serves": ["nemotron35"],
            }],
            "default_provider": "wiremock-working",
            "strict_free": false,
            "corpus_path": home.join("model_corpus.json"),
            "ledger_path": home.join("ledger.jsonl"),
            "health_path": home.join("health.json"),
        });
        std::fs::write(
            home.join("config.json"),
            serde_json::to_string_pretty(&body).unwrap(),
        )
        .unwrap();

        // "nemotron35" arrives via `reviewer_chain` (the scenario-routed
        // pool) — NOT `model_override` — so it must dispatch literally
        // regardless of the colliding `[agents.nemotron35]` alias above.
        let cli = dummy_cli();
        let c = complete_once(
            &cli,
            None,
            &["nemotron35".to_string()],
            "sys",
            "user",
            2048,
            Some(&engine_config),
        )
        .await
        .expect("a scenario-routed literal model id must dispatch");
        assert_eq!(
            c.model, "nemotron35",
            "a scenario-routed literal model id must never be rewritten to \
             a colliding alias's configured model"
        );

        let requests = server.received_requests().await.unwrap_or_default();
        assert_eq!(requests.len(), 1, "exactly one dispatch should have fired");
        let sent: serde_json::Value =
            serde_json::from_slice(&requests[0].body).expect("request body is JSON");
        assert_eq!(
            sent.get("model").and_then(|v| v.as_str()),
            Some("nemotron35"),
            "the wire request must carry the literal pinned model id, not \
             'decoy-model' from the colliding alias"
        );
    }

    /// **REGRESSION: 2026-07-07 reviewer-pipeline fix.** A chain of
    /// `[broken-model, working-model]` MUST fall through from the failing
    /// head to the working tail and produce a real completion from the
    /// second candidate. This pins the production incident
    /// (`deepseek-ai/deepseek-coder-6.7b-instruct` was the broken head
    /// on an Enterprise LLM Gateway) at the dispatch boundary: the new behaviour is
    /// "the broken head's 404 is treated as fallback-worthy; the next
    /// candidate takes over and the review completes." Before the fix
    /// this test would have surfaced the verbatim `404 Not Found`
    /// error from the head and `cmd_review` would have bailed with
    /// `0/1 reviewers completed`.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_chain_falls_through_from_breaking_head_to_working_tail() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        mount_404_function_not_found(&server).await;
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            // The chain the spec demands: operator-written
            // comma-separated candidate list, head first.
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli = Cli::try_parse_from([
            "zoder",
            "exec",
            "--reviewer-allowed-routes",
            "wiremock-broken=broken-model/coder-6.7b,wiremock-working=working-model/glm-5.1",
        ])
        .unwrap();
        let result = complete_once(
            &cli,
            None,
            &[],
            "You are a reviewer.",
            "review this diff",
            2048,
            None,
        )
        .await;
        let c = result.expect("the chain must produce a completion; the broken head must fall through to the working tail");
        assert_eq!(
            c.model, "working-model/glm-5.1",
            "fallback must report the working model's id (the one that actually answered)"
        );
        assert!(
            c.content.contains("working reviewer ok"),
            "must surface the working reviewer's content; got: {}",
            c.content
        );
        assert!(
            c.cost_usd >= 0.0,
            "cost must be reported (zero is acceptable for a free model); got {}",
            c.cost_usd
        );
    }

    /// **REGRESSION GUARD: chain exhaustion.** When EVERY candidate in
    /// the chain returns a fallback-worthy error, the dispatcher must
    /// surface a single composite failure — it MUST NOT silently report
    /// success, MUST NOT downgrade to "approve" on a totally-failed
    /// chain, and MUST clearly state which models were tried. This
    /// pins the "a review that no model produced must not be reported
    /// as success" invariant (`crates/zoder-cli`, the regression-guard
    /// comment in `cmd_review`'s `ok_models == 0` branch).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_chain_exhaustion_reports_0_of_n_in_failure_message() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        // BOTH URLs return 404 — every candidate in the chain must
        // fail and trigger the "no candidate answered" surface.
        mount_404_function_not_found(&server).await;
        // Pin the behavior to "both endpoints return a 404 Function not
        // found" so the test asserts the chain-exhaustion contract, not
        // the URL-default behavior. URL path matches
        // `endpoint_url`'s shape for an openai-chat provider whose
        // base_url has no `/v1` (it appends `/v1/<suffix>`).
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(404).set_body_string(
                r#"{"status":404,"title":"Not Found","detail":"Function not found"}"#,
            ))
            .mount(&server)
            .await;

        write_corpus(&home, &["broken-model/coder-6.7b", "broken-model/other"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,broken-model/other",
        );

        let cli = dummy_cli();
        let result = complete_once(&cli, None, &[], "sys", "user", 2048, None).await;
        let err =
            result.expect_err("every candidate errored; complete_once must surface a failure");
        let msg = format!("{err:#}");
        // The chain-exhausted message MUST mention `reviewer`
        // (so the caller's `cmd_review` knows this is a reviewer
        // failure) and MUST surface an HTTP 404 substring so a
        // CI maintainer can tell from the log that the failure
        // is an upstream "model not deployed" rather than a local
        // // config error.
        assert!(
            msg.contains("reviewer"),
            "error message must mention reviewer: {msg}"
        );
        assert!(
            msg.contains("404") || msg.to_lowercase().contains("not found"),
            "error message must surface the underlying 404 / not-found diagnostic: {msg}"
        );
        // Critical: when the user (not the dispatcher) is the
        // tail-end consumer (e.g. `cmd_review`'s
        // `ok_models == 0` branch), they MUST see a non-zero
        // exit so CI doesn't green-light the review. The
        // `Err(anyhow!(...))` return path here guarantees that:
        // it propagates as a non-zero exit through `cmd_review`'s
        // existing `if ok_models == 0 { anyhow::bail!(...) }`
        // check. This test pins the dispatcher's contribution
        // to that surface (a non-Ok return value).
    }

    /// **REGRESSION GUARD: single-model config behaves identically to
    /// today.** A config that writes `reviewer_model` as a one-element
    /// (no comma) string MUST return a one-element chain in
    /// `complete_once` and the call site MUST see the EXACT same error
    /// shape it would have under the pre-fix code path: a single
    /// 404, no automatic fallback to a different model. This is the
    /// "additive, not breaking" requirement: an operator who has never
    /// written a CSV chain continues to get exactly the old behavior.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn single_model_reviewer_config_behaves_identically_to_today() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        mount_404_function_not_found(&server).await;

        write_corpus(&home, &["broken-model/coder-6.7b"]);
        write_config(
            &home,
            &server.uri(),
            // Single model id, NO comma — the legacy shape. The
            // dispatcher MUST treat this as a one-element chain and
            // pass the head's 404 through verbatim (no fallback
            // available, no chain to walk).
            "broken-model/coder-6.7b",
        );

        let cli = dummy_cli();
        let result = complete_once(&cli, None, &[], "sys", "user", 2048, None).await;
        let err = result.expect_err(
            "single-model config + failing backend must still error (the legacy behavior was \
             to surface the head's error); the new chain logic must not 'succeed' by \
             silently degrading",
        );
        let msg = format!("{err:#}");
        assert!(
            msg.contains("reviewer"),
            "single-model failure must mention the reviewer role: {msg}"
        );
        // The historical error message format is preserved: the
        // call site (cmd_review) receives an `anyhow::Error`
        // whose `.to_string()` already includes the head's
        // exact failure. Existing CI parsers + log filters
        // match on this shape, so preserving it byte-for-byte
        // is essential.
        assert!(
            msg.to_lowercase().contains("404") || msg.to_lowercase().contains("not found"),
            "single-model failure must surface the 404 from the head verbatim: {msg}"
        );
    }

    /// **SPECIFIC-CLASS FALLBACK-WORTHINESS.** Pin that the 404
    /// "Function not found" provider error — the EXACT class of
    /// failure that was reproduced in the 2026-07-07 incident —
    /// flows back to the dispatcher as `FallbackWorthy` (NOT `Fatal`).
    /// The classifier is shared with the author-path chain
    /// (`provider.stream_chat`'s `ErrKind::Http` errors are never
    /// emitted-on-the-stream, so they are never tagged with
    /// `emitted: true` — the dispatcher treats ALL provider-level
    /// errors as `FallbackWorthy`). This test exercises the same
    /// provider error shape the production code raised, and asserts
    /// the NEXT candidate is tried (i.e. the dispatcher did NOT halt
    /// on a `Fatal`).
    ///
    /// Implemented end-to-end: the chain is
    /// `[broken-model, working-model]` and both endpoints 404 —
    /// evidence that the first 404 was classified as `FallbackWorthy`
    /// (NOT `Fatal`) is implicit in the second one being attempted.
    /// Without that classification, the dispatcher would have halted
    /// on the head's error and the working-model URL would have been
    /// untouched. Wiremock records request counts per mounted
    /// expectation; the assertion verifies the second mount received
    /// >= 1 hit.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn function_not_found_404_is_fallback_worthy_not_fatal() {
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        mount_404_function_not_found(&server).await;
        // Mount a 404 for the WORKING model too — combined with the
        // chain below, this means every candidate fails, but the
        // message we'll see is from the LAST attempted candidate
        // (the working one). The point of THIS test is the
        // classification: if the head's 404 was `Fatal`, the chain
        // would halt on the head and the working mount would be hit
        // ZERO times. We assert that the working mount was hit AT
        // LEAST once — which is the literal proof that the head's
        // 404 was classified as `FallbackWorthy` and the dispatcher
        // advanced to the next candidate.
        let working_404_mount = Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(404).set_body_string(
                r#"{"status":404,"title":"Not Found","detail":"Function not found"}"#,
            ))
            .mount_as_scoped(&server)
            .await;

        write_corpus(&home, &["broken-model/coder-6.7b", "working-model/glm-5.1"]);
        write_config(
            &home,
            &server.uri(),
            "broken-model/coder-6.7b,working-model/glm-5.1",
        );

        let cli = dummy_cli();
        let result = complete_once(&cli, None, &[], "sys", "user", 2048, None).await;
        // Drop the scoped mount NOW so wiremock's request count for
        // it stops incrementing (we already took our reading
        // through the dispatcher error path; nothing after this
        // should call the wiremock server). This is a per-test
        // isolation step that doesn't affect correctness — the
        // server still answers subsequent requests via the scoped
        // drop's internal cleanup.
        drop(working_404_mount);
        let err =
            result.expect_err("every candidate errored; chain exhaustion must surface as an error");
        let msg = format!("{err:#}");
        // The literal proof the dispatcher classified the head's 404
        // as `FallbackWorthy` and advanced to the next candidate is
        // the working mount receiving >= 1 hit. Wiremock records
        // that internally; we can ask the server how many requests
        // it has seen. The exact dial: the head returned a 404
        // (dispatcher treated it as `FallbackWorthy`, advanced,
        // called the tail), the tail also 404'd (chain exhausted,
        // we surface an Err). Both endpoints received a request,
        // therefore the head's classification was NOT `Fatal`.
        let requests = server.received_requests().await.unwrap_or_default();
        let paths: Vec<String> = requests.iter().map(|r| r.url.path().to_string()).collect();
        // Defensive ordering: at minimum, both URLs must have
        // received a request (otherwise the chain halted). The URL
        // shape we observe is what `endpoint_url` builds: the
        // `openai-chat` provider whose base_url has no `/v1` appends
        // `/v1/<suffix>` automatically. Both `/broken/v1/...` and
        // `/working/v1/...` should be present.
        assert!(
            paths.iter().any(|p| p.contains("/broken/")),
            "head's URL must have been tried (chain did NOT halt on the head; the head's 404 was classified as FallbackWorthy): paths={paths:?}"
        );
        assert!(
            paths.iter().any(|p| p.contains("/working/")),
            "tail's URL must have been tried (chain advanced past the head's 404 to the next candidate; the head's 404 was classified as FallbackWorthy): paths={paths:?}"
        );
        // Defensive message content: the surfaced error mentions
        // both 404 and "not found" / "function not found" so a CI
        // maintainer reading the log can see WHY every candidate
        // failed and which provider model-id is missing.
        assert!(
            msg.contains("404") && msg.to_lowercase().contains("not found"),
            "chain-exhausted surface must include both 404 and the 'not found' diagnostic so the operator sees what went wrong: {msg}"
        );
        // A `Fatal` outcome would have returned a policy /
        // structural error template — these specific tokens only
        // appear when the dispatcher is in the `FallbackWorthy`
        // branch. Recording them gives the regression a second
        // witness independent of the wiremock request count.
        assert!(
            msg.contains("reviewer"),
            "FallbackWorthy path wraps the provider error with the role ('reviewer'), not the structural-error template: {msg}"
        );
        // No fabricated "approve" verdict — even a fully-failed
        // chain must not invent a positive signal.
        assert!(
            !msg.to_lowercase().contains("approve"),
            "404'd single-model dispatch must NOT silently produce an 'approve' verdict (the no-review-completed contract): {msg}"
        );
    }

    // Suppress the unused-import lint for `Provider` and `PathBuf` —
    // they're scaffolding the type-system expectation of a future
    // test that wires up an `OpenAiProvider` directly. They're
    // harmless here and we want to keep the import set self-
    // documenting (this module is THE seam for adding more end-to-
    // end reviewer tests).
    #[allow(dead_code)]
    fn _unused_import_anchor(_: &Provider, _: &PathBuf) {}

    /// **MR !1 finding (issue #13 port): reviewer SUCCESS path must
    /// record to the health store.** The pre-port code only recorded
    /// failure on a fallback-worthy / policy-violation arm; a clean
    /// reviewer call left the health store stale. After this slice
    /// `dispatch_reviewer_for_model` calls `HealthStore::mutate_locked`
    /// with `record_success(model, elapsed_ms)` on the success path so
    /// the routing signal on the reviewer model refreshes after each
    /// successful review. Without this regression guard a future
    /// refactor that drops the success-record call (a one-line
    /// change that compiles cleanly) would silently stale the breaker
    /// on every reviewer model.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_success_records_breaker_record() {
        use crate::HealthStore;
        let home_dir = tempfile::tempdir().expect("tempdir");
        let home = home_dir.path().to_path_buf();
        let _g = HomeGuard::new(&home);

        let server = MockServer::start().await;
        // Single working model: a clean chain must produce a real
        // completion without any fallback-worthy errors, so we can
        // verify the SUCCESS path of `dispatch_reviewer_for_model`.
        mount_200_openai_chat_completion(&server).await;

        write_corpus(&home, &["working-model/glm-5.1"]);
        write_config(&home, &server.uri(), "working-model/glm-5.1");

        // Pre-condition: the health store is empty for this model.
        let health_path = home.join("health.json");
        let pre = HealthStore::load(&health_path);
        assert!(
            !pre.models.contains_key("working-model/glm-5.1"),
            "pre-condition: health store must not have a record for the reviewer model before dispatch"
        );

        let cli = dummy_cli();
        let result = complete_once(&cli, None, &[], "sys", "user", 2048, None).await;
        let c = result.expect("a clean reviewer call must return Ok");
        assert_eq!(c.model, "working-model/glm-5.1");
        assert!(c.content.contains("working reviewer ok"));

        // Post-condition: the SUCCESS path recorded the breaker.
        let post = HealthStore::load(&health_path);
        let entry = post
            .models
            .get("working-model/glm-5.1")
            .expect("reviewer success MUST record a health entry for the winning model");
        assert_eq!(
            entry.calls, 1,
            "reviewer success MUST increment calls on the breaker; got entry={entry:?}"
        );
        assert_eq!(
            entry.failures, 0,
            "reviewer success MUST NOT increment failures on the breaker; got entry={entry:?}"
        );
        assert_eq!(
            entry.consecutive_failures, 0,
            "reviewer success MUST NOT touch consecutive_failures on the breaker; got entry={entry:?}"
        );
        assert!(
            entry.ewma_latency_ms.is_some(),
            "reviewer success MUST record ewma_latency_ms (a non-zero latency was measured); got entry={entry:?}"
        );
    }

    #[test]
    fn window_budget_plans_one_chunk_and_fits_dispatch_window() {
        let window = 50_000;
        let budget = single_review_budget(Some(window), 10_240, 400_000, 9_000);
        let diff = synthetic_loop_diff(10, 450);
        assert!(
            (140_000..160_000).contains(&diff.len()),
            "fixture should be about 150 KB"
        );
        assert!(
            diff.len() < budget,
            "fixture must fit the single-review budget"
        );
        let prepared = crate::review_diff::prepare_review_diff_with_chunks(
            &[],
            &diff,
            &[],
            &[],
            400_000,
            budget,
            64,
            false,
        )
        .unwrap();
        assert_eq!(prepared.chunks.len(), 1);
        let users = build_review_users("branch", "", "", &prepared, 0, &|_, _| String::new());
        assert_eq!(
            crate::context_opt::fit_prompt(REVIEW_SYSTEM, &users[0], Some(window)).unwrap(),
            crate::context_opt::WindowOutcome::Fits,
            "the window-derived budget must leave enough room for the actual review prompt"
        );
    }

    #[test]
    fn window_budget_overflow_falls_back_to_chunk_cap_and_no_window_stays_strict() {
        let window = 50_000;
        let budget = single_review_budget(Some(window), 10_240, 400_000, 9_000);
        let diff = synthetic_loop_diff(10, 457);
        assert!(diff.len() > budget);
        assert!(
            diff.len() - budget < 5_000,
            "fixture should just exceed the budget: {} bytes vs {budget}",
            diff.len()
        );
        let prepared = crate::review_diff::prepare_review_diff_with_chunks(
            &[],
            &diff,
            &[],
            &[],
            400_000,
            9_000,
            64,
            true,
        )
        .unwrap();
        assert!(prepared.chunks.len() > 1);
        assert_eq!(single_review_budget(None, 10_240, 400_000, 9_000), 9_000);
        let no_window_plan = crate::review_diff::prepare_review_diff_with_chunks(
            &[],
            &synthetic_loop_diff(10, 450),
            &[],
            &[],
            400_000,
            9_000,
            64,
            true,
        )
        .unwrap();
        assert!(no_window_plan.chunks.len() > 1);
        let caps = review_caps(9_000, 400_000);
        assert!(review_plan_matches(caps, Some(50_000), caps, Some(50_000)));
        assert!(!review_plan_matches(caps, Some(30_000), caps, Some(50_000)));
        assert_ne!(
            single_review_budget(Some(30_000), 10_240, 400_000, 9_000),
            single_review_budget(Some(50_000), 10_240, 400_000, 9_000),
            "identical caps with different route windows need distinct plans"
        );
    }

    // ---- loop review base / chunking / fail-closed (2026-10-21) ----

    fn review_caps(hunk: usize, diff: usize) -> crate::review_diff::ReviewCaps {
        crate::review_diff::ReviewCaps {
            max_hunk_bytes: hunk,
            max_diff_bytes: diff,
            max_chunks: 64,
            max_tokens_floor: None,
            from_route: false,
        }
    }

    fn synthetic_loop_diff(files: usize, filler_lines: usize) -> String {
        let mut out = String::new();
        for n in 0..files {
            out.push_str(&format!(
                "diff --git a/f{n}.txt b/f{n}.txt\n--- a/f{n}.txt\n+++ b/f{n}.txt\n@@ -1 +1,{} @@\n-old-{n}\n+new-{n}\n",
                filler_lines + 1
            ));
            for line in 0..filler_lines {
                out.push_str(&format!("+filler {n}/{line} ....................\n"));
            }
        }
        out
    }

    /// REGRESSION: the loop used to build ONE prompt from `cap_diff(diff,
    /// 100_000)`, which keeps only the head and tail of an oversized diff. A
    /// reviewer could then approve hunks it never saw. Every changed line must
    /// now appear in exactly one chunk.
    #[test]
    fn loop_review_chunks_every_hunk_instead_of_truncating() {
        let diff = synthetic_loop_diff(12, 12);
        let plan = plan_loop_review(
            &diff,
            "branch",
            "task\n",
            review_caps(400, 100_000),
            &[],
            &[],
            false,
            &|_, _| String::new(),
            8192,
        )
        .expect("a diff under the total cap must chunk");
        assert!(plan.users.len() > 1, "a 12-file diff must span chunks");
        for n in 0..12 {
            assert!(
                plan.users.iter().any(|u| u.contains(&format!("+new-{n}"))),
                "file {n} was dropped instead of chunked"
            );
        }
        assert!(plan.users.iter().all(|u| u.len() < 400 * 3 + 2_000));
    }

    /// REGRESSION: a diff above the total cap must FAIL CLOSED. Silently
    /// truncating it (the old `cap_diff` path) let the reviewer approve an
    /// incomplete view; an unattempted review is not a review.
    #[test]
    fn loop_review_over_total_cap_fails_closed() {
        let diff = synthetic_loop_diff(4, 40);
        let err = plan_loop_review(
            &diff,
            "branch",
            "task\n",
            review_caps(500, 200),
            &[],
            &[],
            false,
            &|_, _| String::new(),
            8192,
        )
        .expect_err("over-cap diff must be refused, not truncated");
        assert!(
            err.to_string().contains("above the") && err.to_string().contains("limit"),
            "error must name the cap: {err}"
        );
        // An exclusion set that removes every changed file must also refuse.
        let err = plan_loop_review(
            &synthetic_loop_diff(1, 1),
            "branch",
            "task\n",
            review_caps(9_000, 120_000),
            &[],
            &["*.txt".to_string()],
            false,
            &|_, _| String::new(),
            8192,
        )
        .expect_err("an exclusion-emptied diff must not become an empty approve");
        assert!(err.to_string().contains("exclusions removed every file"));
        // An acquisition-truncated diff must be refused even if the configured
        // total cap would accept its (partial) byte length.
        let truncated = format!(
            "{}\n...[git diff truncated during acquisition at 1048576 bytes]...\n",
            synthetic_loop_diff(1, 1)
        );
        let err = plan_loop_review(
            &truncated,
            "branch",
            "task\n",
            review_caps(9_000, 120_000),
            &[],
            &[],
            false,
            &|_, _| String::new(),
            8192,
        )
        .expect_err("a truncated diff must not be approved");
        assert!(err.to_string().contains("truncated during acquisition"));
    }

    /// REGRESSION: a reviewer error (the observed `provider HTTP 500 ...
    /// Context size has been exceeded`) must return Err from the review step so
    /// the loop records `reviewer_unavailable` and an UNRESOLVED iteration. It
    /// must never synthesize an approve.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_provider_error_is_incomplete_and_never_approves() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(500).set_body_string(
                r#"{"error":{"code":500,"message":"Context size has been exceeded.","type":"server_error"}}"#,
            ))
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = dummy_cli();
        let err = run_loop_review(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            ADVERSARIAL_SYSTEM,
            &synthetic_loop_diff(1, 1),
            "branch",
            "task\n",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            home,
        )
        .await
        .expect_err("a failed reviewer call is an incomplete review");
        assert!(
            err.to_string().contains("500") || err.to_string().contains("Context size"),
            "the provider error must survive into the loop diagnostic: {err}"
        );
        let synthesized = synthesize_reviewer_unavailable(&format!("review incomplete: {err}"));
        assert_eq!(synthesized.verdict, REVIEWER_UNAVAILABLE_VERDICT);
        assert!(!loop_review_ok(&synthesized, 0));
        assert!(!explicit_loop_approval(&synthesized, 0));
    }

    /// A multi-chunk loop review must actually SEND every chunk (one request
    /// per chunk) and merge the verdicts — no chunk is silently skipped.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_sends_every_chunk_to_the_reviewer() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        mount_200_openai_chat_completion(&server).await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = dummy_cli();
        let diff = synthetic_loop_diff(20, 20);
        let (review, model, _cost, chunks, _verdicts) = run_loop_review(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            ADVERSARIAL_SYSTEM,
            &diff,
            "branch",
            "task\n",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            home,
        )
        .await
        .expect("every chunk approves");
        assert!(chunks > 1, "20 file sections must span more than one chunk");
        assert_eq!(review.verdict, "approve");
        assert_eq!(model.as_deref(), Some("working-model/reviewer"));
        let requests = server.received_requests().await.unwrap();
        assert_eq!(
            requests.len(),
            chunks,
            "exactly one reviewer request per chunk, no skipped chunk"
        );
        let joined: String = requests
            .iter()
            .map(|r| String::from_utf8_lossy(&r.body).to_string())
            .collect::<Vec<_>>()
            .join("\n");
        for n in 0..20 {
            assert!(
                joined.contains(&format!("+new-{n}")),
                "chunk for file {n} was never sent to the reviewer"
            );
        }
    }
    // ---- loop record: review completeness and finding identity (2026-10-23) ----

    /// A complete review in which EVERY chunk (a 3-of-3-style review: all
    /// chunks structured, from the requested reviewer) returns a structured
    /// verdict. The loop record must call this review COMPLETE: one
    /// `reviewer_verdicts` entry per reviewer with `complete: true` — the
    /// evidence the iteration-level `review_complete` predicate and the
    /// fleet's loop triage key on.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_complete_when_every_chunk_is_structured() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        mount_200_openai_chat_completion_with_findings(&server).await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = dummy_cli();
        let diff = synthetic_loop_diff(20, 100);
        let (review, model, _cost, chunks, reviewer_verdicts) = run_loop_review(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            ADVERSARIAL_SYSTEM,
            &diff,
            "branch",
            "task\n",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            home,
        )
        .await
        .expect("a fully structured multi-chunk review completes");
        // 20 file sections span at least 3 chunks: a 3-of-3 (or larger)
        // structured review.
        assert!(
            chunks >= 3,
            "the review must span at least 3 chunks: {chunks}"
        );
        assert_eq!(model.as_deref(), Some("working-model/reviewer"));
        assert_eq!(review.verdict, "approve");
        // Exactly ONE per-reviewer entry (not one per chunk), complete.
        assert_eq!(
            reviewer_verdicts.len(),
            1,
            "one entry per reviewer, never one per chunk"
        );
        let v = &reviewer_verdicts[0];
        assert_eq!(v["model"], "working-model/reviewer");
        assert_eq!(v["verdict"], "approve");
        assert_eq!(
            v["complete"], true,
            "every requested reviewer returned a structured verdict for every chunk"
        );
        assert!(
            v["escalation_reason"].is_null(),
            "the first candidate answered, so escalation_reason must be null"
        );
        assert_eq!(
            v["skipped_candidates"].as_array().map(Vec::len),
            Some(0),
            "no candidate was skipped"
        );
        assert_eq!(v["forced_family_conflict"], false);
        // The iteration-level predicate the record stores as `review_complete`:
        // non-empty verdicts, all complete.
        let review_complete = iteration_review_complete(&reviewer_verdicts);
        assert!(review_complete);
    }

    /// A reviewer that produces NO structured verdict (provider 500 on every
    /// attempt, e.g. the observed `Context size has been exceeded`) is an
    /// INCOMPLETE review: the review errors, the synthesized verdict is
    /// `reviewer_unavailable`, and the Err path contributes NO reviewer
    /// verdicts, so the iteration-level predicate is false.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_incomplete_when_reviewer_times_out_or_fails() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(500).set_body_string(
                r#"{"error":{"code":500,"message":"Context size has been exceeded.","type":"server_error"}}"#,
            ))
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = dummy_cli();
        let err = run_loop_review(
            &cli,
            &test_engine(),
            None,
            &[],
            &[],
            ADVERSARIAL_SYSTEM,
            &synthetic_loop_diff(1, 1),
            "branch",
            "task\n",
            Some("working-model/reviewer"),
            None,
            &[],
            &[],
            home,
        )
        .await
        .expect_err("a failed reviewer call is an incomplete review");
        let detail = format!("review incomplete: {err}");
        let synthesized = synthesize_reviewer_unavailable(&detail);
        assert_eq!(synthesized.verdict, REVIEWER_UNAVAILABLE_VERDICT);
        assert!(!loop_review_ok(&synthesized, 0));
        // The Err path contributes NO reviewer verdicts; the record's
        // `review_complete` predicate must be false for them.
        let reviewer_verdicts: Vec<serde_json::Value> = Vec::new();
        let review_complete = iteration_review_complete(&reviewer_verdicts);
        assert!(
            !review_complete,
            "a failed review can never be recorded complete"
        );
    }

    /// REGRESSION (PARTIAL): when one chunk never yields a structured verdict
    /// even after its repair retry, the whole review is refused. A review that
    /// did not cover every chunk is PARTIAL and incomplete — never complete.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_partial_chunk_is_incomplete() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        let hits = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let counter = hits.clone();
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(move |_: &wiremock::Request| {
                let n = counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                // First request: structured approve. Second (the repair of the
                // second chunk): prose again — the chunk stays unstructured.
                let content = if n == 0 {
                    r#"{"verdict":"approve","summary":"ok","findings":[],"next_steps":[]}"#
                        .to_string()
                } else {
                    "prose only, no json".to_string()
                };
                ResponseTemplate::new(200).set_body_json(
                    json!({"choices":[{"message":{"content":content},"finish_reason":"stop"}]}),
                )
            })
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let err = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/reviewer"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["chunk one".into(), "chunk two".into()],
            2048,
            None,
            &|_| None,
        )
        .await;
        // Three requests: chunk 1 + chunk 2 first attempt + the
        // (also-prose) repair of chunk 2.
        assert_eq!(hits.load(std::sync::atomic::Ordering::SeqCst), 3);
        let err = err.expect_err("a chunk without a structured verdict fails the review");
        assert!(
            err.to_string().contains("invalid JSON twice"),
            "the diagnostic must name the unstructured chunk: {err}"
        );
    }

    /// The chunk report the loop record keys on: ONE report per call (a call
    /// is one reviewer's chunks — callers fan out to a panel by calling
    /// once per slot, never by passing multiple reviewers), with model
    /// identity as an explicit `Option` — `None` is "no chunk completed",
    /// never an empty string.
    #[test]
    fn reviewer_chunk_report_is_one_per_call_and_model_identity_is_explicit() {
        // An empty review: no chunk completed, so both model identities are
        // ABSENT (None), not fabricated as "".
        let empty = ReviewerChunkReport {
            requested_model: None,
            served_model: None,
            chunks: Vec::new(),
            skipped: Vec::new(),
            escalation_reason: None,
            forced_family_conflict: false,
        };
        assert!(
            empty.requested_model.is_none(),
            "absent, not an empty string"
        );
        assert!(empty.served_model.is_none(), "absent, not an empty string");
        assert!(empty.chunks.is_empty());
        // A completed single-chunk review: both identities present.
        let done = ReviewerChunkReport {
            requested_model: Some("working-model/reviewer".into()),
            served_model: Some("working-model/reviewer".into()),
            chunks: vec![ChunkCompletion {
                requested_model: "working-model/reviewer".into(),
                served_model: "working-model/reviewer".into(),
                structured: true,
            }],
            skipped: Vec::new(),
            escalation_reason: None,
            forced_family_conflict: false,
        };
        assert_eq!(
            done.requested_model.as_deref(),
            Some("working-model/reviewer")
        );
        assert_eq!(done.served_model.as_deref(), Some("working-model/reviewer"));
        assert_eq!(done.chunks.len(), 1);
    }

    /// REGRESSION (provider-side model substitution): the provider answers a
    /// chunk with a model id different from the one requested. The DISPATCH
    /// refuses the reported substitution (provenance mismatch) BEFORE the
    /// chunk walker's own mixed-model check — a substitution must surface as
    /// incomplete, never as complete. (The chunk walker's own mid-review
    /// fallback enforcement is pinned separately by
    /// `loop_review_mid_review_model_fallback_is_incomplete`.)
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn loop_review_served_model_substitution_is_incomplete() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        // The provider answers with a DIFFERENT model id than requested. The
        // dispatch rejects the reported substitution (provenance mismatch).
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "model": "another-model",
                "choices": [{"message": {"content": r#"{"verdict":"approve","summary":"ok","findings":[],"next_steps":[]}"#}, "finish_reason": "stop"}]
            })))
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let err = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/reviewer"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["chunk one".into()],
            2048,
            None,
            &|_| None,
        )
        .await;
        let err = err.expect_err("a mid-review model substitution must fail the review");
        // The error chain carries the dispatch's own diagnostic (the
        // reported substitution is a policy violation), wrapped in the
        // chunk context. A mid-review model change is never a complete review.
        let chain = format!("{err:#}");
        assert!(
            chain.contains("provenance mismatch") || chain.contains("mixed-model"),
            "the diagnostic chain must name the substitution: {chain}"
        );
        assert_eq!(
            server.received_requests().await.unwrap().len(),
            1,
            "the substituted reviewer call is the only one that ran"
        );
    }

    // ------------------------------------------------------------------
    // Regression: an empty completion at finish_reason "length" (a
    // reasoning model that spent the whole max_tokens budget) used to be
    // rejected as "malformed ... empty completion" by the provider parser
    // and never reached the chunk walker's doubled-budget repair. Now:
    // one repair with the doubled (capped) budget, a clear failure when
    // the model comes back empty the second time, and the ledger records
    // both calls.
    // ------------------------------------------------------------------

    /// First response: the reasoning model returns an empty answer at
    /// `finish_reason: "length"` (with reasoning_content and usage).
    /// Second response: a valid verdict JSON. The review must succeed,
    /// the mock must have seen EXACTLY two requests, and the second one
    /// must carry the doubled (capped) max_tokens.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_empty_length_completion_gets_one_doubled_budget_repair() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(move |request: &wiremock::Request| {
                let value: serde_json::Value =
                    serde_json::from_slice(&request.body).unwrap();
                let max_tokens = value.get("max_tokens").and_then(|v| v.as_u64()).unwrap_or(0);
                if max_tokens > 2048 {
                    // The repair call (doubled budget): answer with a verdict.
                    ResponseTemplate::new(200).set_body_json(json!({
                        "choices": [{
                            "message": {"content": r#"{"verdict":"approve","summary":"ok on repair","findings":[],"next_steps":[]}"#},
                            "finish_reason": "stop"
                        }],
                        "usage": {"prompt_tokens": 5, "completion_tokens": 30, "total_tokens": 35}
                    }))
                } else {
                    // First call: the whole 2048 budget burned on reasoning,
                    // no answer.
                    ResponseTemplate::new(200).set_body_json(json!({
                        "choices": [{
                            "message": {"role": "assistant", "content": "", "reasoning_content": "long hidden reasoning"},
                            "finish_reason": "length"
                        }],
                        "usage": {"prompt_tokens": 5, "completion_tokens": 2048, "total_tokens": 2053}
                    }))
                }
            })
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let (completion, report) = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/reviewer"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["chunk one".into()],
            2048,
            None,
            &|_| None,
        )
        .await
        .expect("a budget exhaustion repaired with the doubled budget succeeds");
        // The verdict came back (on the repair) — the review is complete.
        let review = strict_review(&completion.content).expect("the repair's verdict must parse");
        assert_eq!(review.verdict, "approve");
        assert!(
            !report.chunks[0].structured,
            "a verdict that only appeared on the repair is not first-attempt structured"
        );
        // EXACTLY two requests: the empty first call + one repair.
        let requests = server.received_requests().await.unwrap();
        assert_eq!(
            requests.len(),
            2,
            "the model must receive exactly two requests"
        );
        let first_tokens: u64 = requests[0]
            .body_json::<serde_json::Value>()
            .ok()
            .and_then(|v| v.get("max_tokens").and_then(|v| v.as_u64()))
            .unwrap();
        let second_tokens: u64 = requests[1]
            .body_json::<serde_json::Value>()
            .ok()
            .and_then(|v| v.get("max_tokens").and_then(|v| v.as_u64()))
            .unwrap();
        assert_eq!(first_tokens, 2048, "the first call ran at the chunk budget");
        assert_eq!(
            second_tokens,
            reviewer_retry_budget(2048) as u64,
            "the repair must carry the doubled budget"
        );
        // Both calls were ledgered (cost unknown rows are acceptable: the
        // provider is free-billed and the catalog is absent in the test
        // home, so the rows land as cost_unknown — they still EXIST, with
        // the usage the provider published).
        let ledger = std::fs::read_to_string(home.join("ledger.jsonl")).unwrap_or_default();
        let rows: Vec<&str> = ledger.lines().filter(|l| !l.trim().is_empty()).collect();
        assert_eq!(
            rows.len(),
            2,
            "both calls must be recorded in the ledger: {ledger}"
        );
        assert!(
            rows.iter()
                .all(|r| r.contains("\"model\":\"working-model/reviewer\"")),
            "every ledger row must name the served model: {ledger}"
        );
    }

    /// Both responses come back empty at `finish_reason: "length"`: the
    /// review must fail with a message that names the model and the
    /// budget, and the mock must have seen exactly two requests (the
    /// repair runs at most once — never a third).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn reviewer_empty_length_completion_twice_fails_with_budget_message() {
        let home_dir = tempfile::tempdir().unwrap();
        let home = home_dir.path();
        let _guard = HomeGuard::new(home);
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/working/v1/chat/completions"))
            .respond_with(ResponseTemplate::new(200).set_body_json(json!({
                "choices": [{
                    "message": {"role": "assistant", "content": "", "reasoning_content": "still thinking"},
                    "finish_reason": "length"
                }],
                "usage": {"prompt_tokens": 5, "completion_tokens": 2048, "total_tokens": 2053}
            })))
            .mount(&server)
            .await;
        write_corpus(home, &["working-model/reviewer"]);
        write_config(home, &server.uri(), "working-model/reviewer");
        let cli = Cli::try_parse_from(["zoder", "exec", "--retries", "0"]).unwrap();
        let err = complete_review_chunks(
            &cli,
            Some(&test_engine()),
            Some("working-model/reviewer"),
            &[],
            &[],
            REVIEW_SYSTEM,
            &["chunk one".into()],
            2048,
            None,
            &|_| None,
        )
        .await
        .expect_err("two consecutive budget exhaustions must fail the review");
        let chain = format!("{err:#}");
        assert!(
            chain.contains("working-model/reviewer"),
            "the diagnostic must name the model: {chain}"
        );
        assert!(
            chain.contains("spent its whole 2048-token budget") && chain.contains("(twice)"),
            "the diagnostic must name the budget and that it happened twice: {chain}"
        );
        assert!(
            chain.contains("doubled 4096-token budget"),
            "the diagnostic must name the repair budget too: {chain}"
        );
        assert!(
            chain.contains("lower its reasoning effort or raise max_tokens"),
            "the diagnostic must carry the operator remedy: {chain}"
        );
        // Exactly two requests: first attempt + the single repair. No
        // third call, no chain-advance retry of the same model.
        assert_eq!(
            server.received_requests().await.unwrap().len(),
            2,
            "the repair runs at most once"
        );
        // Both calls were ledgered.
        let ledger = std::fs::read_to_string(home.join("ledger.jsonl")).unwrap_or_default();
        let rows: Vec<&str> = ledger.lines().filter(|l| !l.trim().is_empty()).collect();
        assert_eq!(
            rows.len(),
            2,
            "both calls must be recorded in the ledger: {ledger}"
        );
    }

    /// The `content: null` variant of the same regression: an explicit
